use std::{
    io::Cursor,
    path::{Path, PathBuf},
};

use flate2::read::GzDecoder;
use fuels_accounts::provider::SUPPORTED_FUEL_CORE_VERSION;
use tar::Archive;

struct Downloader {
    dir: PathBuf,
}

impl Downloader {
    const EXECUTOR_FILE_NAME: &'static str = "fuel-core-wasm-executor.wasm";

    pub fn new() -> Self {
        let env = std::env::var("OUT_DIR").unwrap();
        let out_dir = Path::new(&env);
        Self {
            dir: out_dir.to_path_buf(),
        }
    }

    pub fn should_download(&self) -> anyhow::Result<bool> {
        if !self.executor_path().exists() {
            return Ok(true);
        }

        if !self.version_path().exists() {
            return Ok(true);
        }

        let saved_version = semver::Version::parse(&std::fs::read_to_string(self.version_path())?)?;
        if saved_version != SUPPORTED_FUEL_CORE_VERSION {
            return Ok(true);
        }

        Ok(false)
    }

    pub fn download(&self) -> anyhow::Result<()> {
        std::fs::create_dir_all(&self.dir)?;

        const LINK_TEMPLATE: &str = "https://github.com/FuelLabs/fuel-core/releases/download/vVERSION/fuel-core-VERSION-x86_64-unknown-linux-gnu.tar.gz";
        let link = LINK_TEMPLATE.replace("VERSION", &SUPPORTED_FUEL_CORE_VERSION.to_string());

        let response = reqwest::blocking::Client::builder()
            .timeout(std::time::Duration::from_secs(60))
            .build()?
            .get(link)
            .send()?;

        if !response.status().is_success() {
            anyhow::bail!("Failed to download wasm executor: {}", response.status());
        }

        let mut content = Cursor::new(response.bytes()?);

        let mut archive = Archive::new(GzDecoder::new(&mut content));

        let mut extracted = false;
        let executor_in_tar = Path::new(&format!(
            "fuel-core-{SUPPORTED_FUEL_CORE_VERSION}-x86_64-unknown-linux-gnu"
        ))
        .join(Self::EXECUTOR_FILE_NAME);

        for entry in archive.entries()? {
            let mut entry = entry?;

            if entry.path()? == executor_in_tar {
                entry.unpack(self.executor_path())?;
                std::fs::write(
                    self.version_path(),
                    format!("{SUPPORTED_FUEL_CORE_VERSION}"),
                )?;

                extracted = true;
                break;
            }
        }
        if !extracted {
            anyhow::bail!("Failed to extract wasm executor from the archive");
        }

        Ok(())
    }

    fn make_cargo_watch_downloaded_files(&self) {
        let executor_path = self.executor_path();
        println!("cargo:rerun-if-changed={}", executor_path.display());

        let version_path = self.version_path();
        println!("cargo:rerun-if-changed={}", version_path.display());
    }

    fn executor_path(&self) -> PathBuf {
        self.dir.join(Self::EXECUTOR_FILE_NAME)
    }

    fn version_path(&self) -> PathBuf {
        self.dir.join("version.rs")
    }
}

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    let downloader = Downloader::new();
    downloader.make_cargo_watch_downloaded_files();

    if downloader.should_download().unwrap() {
        downloader.download().unwrap();
    }
}

use fuels::{
    accounts::signers::kms::aws::{
        AwsKmsSigner,
        aws_config::{BehaviorVersion, Region, defaults},
        aws_sdk_kms::{
            Client,
            config::Credentials,
            types::{KeySpec, KeyUsageType},
        },
    },
    prelude::Error,
    types::errors::{Context, Result},
};
use testcontainers::{core::ContainerPort, runners::AsyncRunner};
use tokio::io::AsyncBufReadExt;

#[derive(Default)]
pub struct AwsKms {
    show_logs: bool,
}

struct AwsKmsImage;

impl testcontainers::Image for AwsKmsImage {
    fn name(&self) -> &str {
        "localstack/localstack"
    }

    fn tag(&self) -> &str {
        "4.14.0"
    }

    fn ready_conditions(&self) -> Vec<testcontainers::core::WaitFor> {
        vec![testcontainers::core::WaitFor::message_on_stdout("Ready.")]
    }

    fn expose_ports(&self) -> &[ContainerPort] {
        &[ContainerPort::Tcp(4566)]
    }
}

impl AwsKms {
    pub fn with_show_logs(mut self, show_logs: bool) -> Self {
        self.show_logs = show_logs;
        self
    }

    pub async fn start(self) -> Result<AwsKmsProcess> {
        let container = AwsKmsImage
            .start()
            .await
            .map_err(|e| Error::Other(e.to_string()))
            .with_context(|| "Failed to start KMS container")?;

        if self.show_logs {
            spawn_log_printer(&container);
        }

        let port = container
            .get_host_port_ipv4(4566)
            .await
            .map_err(|e| Error::Other(e.to_string()))?;
        let url = format!("http://localhost:{}", port);

        let credentials = Credentials::new("test", "test", None, None, "Static Test Credentials");
        let region = Region::new("us-east-1");

        let config = defaults(BehaviorVersion::latest())
            .credentials_provider(credentials)
            .endpoint_url(url.clone())
            .region(region)
            .load()
            .await;

        let client = Client::new(&config);

        Ok(AwsKmsProcess {
            _container: container,
            client,
            url,
        })
    }
}

fn spawn_log_printer(container: &testcontainers::ContainerAsync<AwsKmsImage>) {
    let stderr = container.stderr(true);
    let stdout = container.stdout(true);
    tokio::spawn(async move {
        let mut stderr_lines = stderr.lines();
        let mut stdout_lines = stdout.lines();

        let mut other_stream_closed = false;
        loop {
            tokio::select! {
                stderr_result = stderr_lines.next_line() => {
                    match stderr_result {
                        Ok(Some(line)) => eprintln!("KMS (stderr): {}", line),
                        Ok(None) if other_stream_closed => break,
                        Ok(None) => other_stream_closed = true,
                        Err(e) => {
                            eprintln!("KMS: Error reading from stderr: {:?}", e);
                            break;
                        }
                    }
                }
                stdout_result = stdout_lines.next_line() => {
                    match stdout_result {
                        Ok(Some(line)) => eprintln!("KMS (stdout): {}", line),
                        Ok(None) if other_stream_closed => break,
                        Ok(None) => other_stream_closed = true,
                        Err(e) => {
                            eprintln!("KMS: Error reading from stdout: {:?}", e);
                            break;
                        }
                    }
                }
            }
        }

        Ok::<(), std::io::Error>(())
    });
}

pub struct AwsKmsProcess {
    _container: testcontainers::ContainerAsync<AwsKmsImage>,
    client: Client,
    url: String,
}

impl AwsKmsProcess {
    pub async fn create_signer(&self) -> anyhow::Result<AwsKmsSigner> {
        let response = self
            .client
            .create_key()
            .key_usage(KeyUsageType::SignVerify)
            .key_spec(KeySpec::EccSecgP256K1)
            .send()
            .await?;

        let id = response
            .key_metadata
            .and_then(|metadata| metadata.arn)
            .ok_or_else(|| anyhow::anyhow!("key arn missing from response"))?;

        let kms_signer = AwsKmsSigner::new(id.clone(), &self.client).await?;

        Ok(kms_signer)
    }

    pub fn client(&self) -> &Client {
        &self.client
    }

    pub fn url(&self) -> &str {
        &self.url
    }
}

use fuels::types::errors::Result;

use crate::aws_kms::{AwsKms, AwsKmsProcess};

pub async fn start_aws_kms(logs: bool) -> Result<AwsKmsProcess> {
    AwsKms::default().with_show_logs(logs).start().await
}
